"""Unit 47: Tagalog Basic Course, Semester II, Chapter 15, Lesson 1: Hospital and Other Medical Services.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, September 2017).
Pictures, audio, partner work and role plays are left out; the book's answer keys are used (misprints noted).
Numbers are written in words in the spoken lines."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


def _dc(ans):
    cap = ans[0].isupper()
    pool = ["magkaroon", "nagkaroon", "nagkakaroon", "magkakaroon"]
    out = []
    for x in pool:
        x = x.capitalize() if cap else x
        if x.lower() != ans.lower() and x not in out:
            out.append(x)
    return out[:3]


def P(rows):
    return [(t, e) for _, t, e in rows]


