        + [F("Madalas ___ ang maraming Pilipino. (get sick)", "magkasakit", ["magkaroon", "magkabahay"], "magkasakit."), F("___ ng hospital ang barangay namin. (will have)", "Magkakaroon", ["Nagkaroon", "Nagkakaroon"], "magkakaroon."), F("___ pala si Gina. (got dengue)", "Nagka-dengue", ["Magka-dengue", "Magkaka-dengue"], "nagka-dengue."), F("Hindi ako ___ sa susunod na linggo. (will have money)", "magkakapera", ["nagkapera", "magkapera"], "magkakapera.")]
